import json, csv, re, urllib.request
from collections import defaultdict
from cvss import CVSS3
from packaging.version import Version

AUDIT_PATH='/root/npm_audit.json'
LOCK_PATH='/root/package-lock.json'
OUT_PATH='/root/security_audit.csv'

with open(AUDIT_PATH) as f:
    audit=json.load(f)
with open(LOCK_PATH) as f:
    lock=json.load(f)

packages_map=lock.get('packages',{})

# Collect advisories per package (high/critical only)
pkg_advisories=defaultdict(dict)  # pkg -> {ghsa: via}
for pkg, v in audit['vulnerabilities'].items():
    for via in v.get('via', []):
        if isinstance(via, dict) and via.get('severity') in ('high','critical'):
            url=via.get('url','')
            ghsa=url.rsplit('/',1)[-1] if url else None
            if ghsa:
                pkg_advisories[pkg][ghsa]=via

# Map package -> vulnerable versions from nodes
pkg_versions=defaultdict(set)
for pkg, v in audit['vulnerabilities'].items():
    if pkg not in pkg_advisories:
        continue
    for node in v.get('nodes', []):
        info=packages_map.get(node)
        if info and 'version' in info:
            pkg_versions[pkg].add(info['version'])

# OSV query cache by (pkg, version)
osv_cache={}

def osv_query(pkg, version):
    key=(pkg, version)
    if key in osv_cache:
        return osv_cache[key]
    url='https://api.osv.dev/v1/query'
    body=json.dumps({'package':{'name':pkg,'ecosystem':'npm'},'version':version}).encode()
    req=urllib.request.Request(url, data=body, headers={'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(req) as r:
            data=json.load(r)
    except Exception:
        data={'vulns': []}
    osv_cache[key]=data.get('vulns', [])
    return osv_cache[key]


def get_osv_vuln(pkg, version, ghsa):
    for vuln in osv_query(pkg, version):
        if vuln.get('id') == ghsa:
            return vuln
    return None


def version_in_range(version, start, end):
    v=Version(version)
    if start and start != '0':
        if v < Version(start.lstrip('v')):
            return False
    if end:
        if v >= Version(end.lstrip('v')):
            return False
    return True


def fixed_for_version(pkg, version, vuln):
    if not vuln:
        return None
    for affected in vuln.get('affected', []):
        pkg_info=affected.get('package', {})
        if pkg_info.get('name') != pkg or pkg_info.get('ecosystem') != 'npm':
            continue
        for r in affected.get('ranges', []):
            if r.get('type') != 'SEMVER':
                continue
            current=None
            for ev in r.get('events', []):
                if 'introduced' in ev:
                    current=ev['introduced']
                if 'fixed' in ev and current is not None:
                    if version_in_range(version, current, ev['fixed']):
                        return ev['fixed']
            # If range has no fixed and version is in it, return None
            if current is not None and any('fixed' in ev for ev in r.get('events', [])) is False:
                if version_in_range(version, current, None):
                    return None
    return None


def cve_from_vuln(vuln):
    if not vuln:
        return None
    aliases=vuln.get('aliases', []) or []
    cves=[a for a in aliases if a.startswith('CVE-')]
    if not cves:
        return None
    return ';'.join(sorted(set(cves)))


def cvss_score(via, vuln):
    score=None
    try:
        score=via.get('cvss', {}).get('score')
        if score and score > 0:
            return f"{score:.1f}" if isinstance(score, float) else str(score)
    except Exception:
        pass
    if vuln:
        for sev in vuln.get('severity', []):
            if sev.get('type') == 'CVSS_V3':
                vec=sev.get('score')
                try:
                    base=CVSS3(vec).scores()[0]
                    return f"{base:.1f}"
                except Exception:
                    continue
    return None

rows=[]
for pkg, advisories in pkg_advisories.items():
    versions=sorted(pkg_versions.get(pkg, []))
    for ghsa, via in advisories.items():
        for version in versions:
            vuln=get_osv_vuln(pkg, version, ghsa)
            cve=cve_from_vuln(vuln) or 'N/A'
            fixed=fixed_for_version(pkg, version, vuln) or 'N/A'
            score=cvss_score(via, vuln) or 'N/A'
            rows.append({
                'Package': pkg,
                'Version': version,
                'CVE_ID': cve,
                'Severity': via.get('severity', '').upper(),
                'CVSS_Score': score,
                'Fixed_Version': fixed,
                'Title': via.get('title','').strip(),
                'Url': via.get('url','').strip(),
            })

# Sort rows for stable output
rows.sort(key=lambda r: (r['Package'], r['Version'], r['CVE_ID'], r['Title']))

with open(OUT_PATH,'w', newline='') as f:
    writer=csv.DictWriter(f, fieldnames=['Package','Version','CVE_ID','Severity','CVSS_Score','Fixed_Version','Title','Url'])
    writer.writeheader()
    writer.writerows(rows)

print(f"Wrote {len(rows)} rows to {OUT_PATH}")
PY"}

